\section{Functional Inclusion $X(t)\subset F(t,X(t))$} \label{s:Func_Em}

Assuming some interplay of the (uniform) boundedness of directional variations and
(uniform) contractions, we have the following parametrized version of Banach's
Contraction Theorem, extending Theorem~11.4 from~\cite{Sovae}.

\begin{thm} \label{t:FuEm}
Suppose a multifunction $F:T\!\times\!\mbox{\rm c}(M)\!\to\!\mbox{\rm c}(M)$
is such that\/{\rm:}
  \begin{itemize}
\item[{\rm(a)}] there is a nondecreasing bounded function $\varphi:T\to\mathbb{R}$ such that
  \begin{equation*}
\mbox{$\!\!\!e(F(s,X),F(t,X))\le\varphi(t)-\varphi(s)$ for all $s,t\in T$, $s\le T$, and
  $X\in\mbox{\rm c}(M);$}
  \end{equation*}

\item[{\rm(b)}] there is a number $0\le\mu<1$ such that
  \begin{equation*}
\mbox{$e(F(t,X),F(t,Y))\le\mu d_H(X,Y)$ for all $t\in T$ and $X,Y\in\mbox{\rm c}(M);$}
  \end{equation*}
\item[{\rm(c)}] there is a multifunction $K:T\to\mbox{\rm c}(M)$ such that
  \begin{equation*}
\mbox{$F(t,X)\subset K(t)$ for all $t\in T$ and $X\in\mbox{\rm c}(M)$.}
  \end{equation*}
  \end{itemize}

If $t_0:=\inf T\in T$ and $X_0\in\mbox{\rm c}(M)$, then there is
$X:T\to\mbox{\rm c}(M)$ such that\\[3pt]
{\rm(i)}~$\mbox{\rm V}(X,T)\le\mbox{\rm V}(\varphi,T)/(1-\mu)<+\infty;$
{\rm(ii)}~$X(t)\subset F(t,X(t))$ for all $t\in T;$\\[3pt]
{\rm(iii)} $d_H(X_0,X(t_0))\le e\bigl(X_0,F(t_0,X(t_0))\bigr)$.
\smallbreak
In addition, if $X_0\subset F(t_0,X_0)$, then {\rm(iii)} can be replaced by $X(t_0)=X_0$.
\end{thm}

\begin{pf}
First, observe that assumptions (a) and (b) and the triangle inequality for $e$ imply,
for all $s,t\in T$, $s\le t$, and $X,Y\in\mbox{c}(M)$,
  \begin{equation} \label{e:XY}
e(F(s,X),F(t,Y))\le\varphi(t)-\varphi(s)+\mu d_H(X,Y).
  \end{equation}

$F_1:T\to\mbox{c}(M)$ and, by \eq{e:XY},
  \begin{equation*}
e(F_1(s),F_1(t))\le\varphi(t)-\varphi(s)+\mu d_H(X_1(s),X_1(t))\quad
  \forall\,s,t\in T,\,\,s\le t.
  \end{equation*}
Arguing with partitions of $T$, Lemma~\ref{l:char} implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_1,T)\le\mbox{\rm V}(\varphi,T)+\mu\mbox{\rm V}(X_1,T)\le(1+\mu)\mbox{\rm V}(\varphi,T).
  \end{equation*}
Applying Theorem~\ref{t:BV} again, we obtain $X_2:T\to\mbox{c}(M)$ such that
$X_2(t)\subset F_1(t)$ for all $t\in T$, $d_H(X_0,X_2(t_0))\le e(X_0,F_1(t_0))$, and
  \begin{equation*}
\mbox{\rm V}(X_2,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_1,T)\le(1+\mu)\mbox{\rm V}(\varphi,T).
  \end{equation*}
If $F_2(t)\!:=\!F(t,X_2(t))$, $t\in T$, then $F_2:T\to\mbox{c}(M)$ and, by \eq{e:XY},
  \begin{equation*}
e(F_2(s),F_2(t))\le\varphi(t)-\varphi(s)+\mu d_H(X_2(s),X_2(t))\quad
  \forall\,s,t\in T,\,\,s\le t,
  \end{equation*}

and so,
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_2,T)\le\mbox{\rm V}(\varphi,T)+\mu\mbox{\rm V}(X_2,T)\le(1+\mu+\mu^2)\mbox{\rm V}(\varphi,T).
  \end{equation*}

Arguing by induction, we obtain the sequence $\{X_n\}_{n=1}^\infty$ of multifunctions
$X_n:T\to\mbox{c}(M)$ such that, given $n\in\mathbb{N}$,
  \begin{eqnarray}
&X_n(t)\subset F_{n-1}(t)\!:=\!F(t,X_{n-1}(t))\subset K(t)\quad\mbox{for all $t\in T$,}&
  \label{e:Xnt}\\[3pt]
&d_H(X_0,X_n(t_0))\le e(X_0,F_{n-1}(t_0))\!=\!e\bigl(X_0,F(t_0,X_{n-1}(t_0))\bigr),
  \,\,\mbox{and}& \label{e:Hot}\\
&\displaystyle\mbox{\rm V}(X_n,T)\le\biggl(\sum_{i=0}^{n-1}\mu^i\biggr)\mbox{\rm V}(\varphi,T)
  \le\frac1{1-\mu}\,\mbox{\rm V}(\varphi,T).& \label{e:Vft}
  \end{eqnarray}

7)]{Sovae}), which is valid for all $X,X',Y,Y'\in\mbox{c}(M)$:
  \begin{equation} \label{e:Sog}
|e(X,Y)-e(X',Y')|\le d_H(X,X')+d_H(Y,Y').
  \end{equation}
In fact, given $t\in T$, \eq{e:Xnt} implies $e\bigl(X_n(t),F(t,X_{n-1}(t))\bigr)=0$,
and so, taking into account \eq{e:Sog} and \eq{e:XY}, we get
  \begin{align*}
e(X(t),F(t,X(t)))&\!=\!\bigl|e(X(t),F(t,X(t)))\!-\!e(X_n(t),F(t,X_{n-1}(t)))\bigr|\\[2pt]
&\!\le\! d_H(X(t),X_n(t))\!+\!d_H(F(t,X(t)),F(t,X_{n-1}(t)))\\[2pt]
&\!\le\! d_H(X(t),X_n(t))\!+\!\mu d_H(X(t),X_{n-1}(t))\to0
  \,\,\,\,\mbox{as}\,\,\,n\to\infty.
  \end{align*}
Thus, $e(X(t),F(t,X(t)))=0$, which implies (by properties of~$e$) assertion~(ii).

To establish (iii), we note that (cf. \eq{e:Hot} and (iii))
  \begin{equation*}
|d_H(X_0,X_n(t_0))-d_H(X_0,X(t_0))|\le d_H(X_n(t_0),X(t_0))\to0
  \,\,\,\,\mbox{as}\,\,\,n\to\infty,
  \end{equation*}
and, by virtue of \eq{e:Sog} and assumption (b),
  \begin{align*}
&\qquad\bigl|e(X_0,F(t_0,X_{n-1}(t_0)))-e(X_0,F(t_0,X(t_0)))\bigr|\\[2pt]
\le&\,d_H(F(t_0,X_{n-1}(t_0)),F(t_0,X(t_0)))\le\mu d_H(X_{n-1}(t_0),X(t_0))
  \to0,\,\,n\to\infty.
  \end{align*}
Passing to the limit as $n\to\infty$ in \eq{e:Hot}, we arrive at~(iii).

Finally, suppose $X_0\!\subset\! F(t_0,X_0)$. Hence $X_0\!\subset\! F_0(t_0)$ and
$e(X_0,F_0(t_0))\!=\!0$. From the above,
$d_H(X_0,X_1(t_0))\!\le\! e(X_0,F_0(t_0))\!=\!0$,
and so, $X_1(t_0)\!=\!X_0$. Since
  \begin{equation*}
X_0\subset F_0(t_0)=F(t_0,X_0)=F(t_0,X_1(t_0))=F_1(t_0),
  \end{equation*}
we find from $d_H(X_0,X_2(t_0))\le e(X_0,F_1(t_0))=0$ that $X_2(t_0)=X_0$.
By induction, we deduce from \eq{e:Hot} that $X_n(t_0)=X_0$ for all $n\in\mathbb{N}$.
Passing to the lmit as $n\to\infty$ in \eq{e:Hot}, we get
$d_H(X_0,X(t_0))\le e(X_0,F(t_0,X_0))=0$, which yields $X(t_0)=X_0$.
\qed\end{pf}

\begin{rem}
If $F(t,X)=F(t)$ is independent of $X\in\mbox{c}(M)$ (or $\mu=0$), Theorem~
\ref{t:FuEm} gives back Theorem~\ref{t:BV}(a): we may set $\varphi=\ori{v}_{F}$
and~$K=F$. On the other hand, if $F(t,X)=F(X)$ is independent of $t\in T$ (or
$\varphi\equiv0$), Theorem~\ref{t:FuEm} is a consequence of Banach's Contraction
Theorem (in fact, $F:\mbox{c}(K)\to\mbox{c}(K)$ is a contraction on compact,
hence complete, metric space $(\mbox{c}(K),d_H)$ with $K=K(t_0)$).
\end{rem}

\begin{exa} \label{ex:6.1}
The purpose of this example is to show that assumptions of Theorem~\ref{t:FuEm}
can be fulfiled. Let $M=\mathbb{B}$ be a Banach space with norm $|\cdot|$ and
