($\ori{\mbox{\rm a}}$) This is a consequence of Lemma~\ref{l:jumps}
($\ori{\mbox{\rm a}}$), since ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})=\ori{v}(t)$ and,
by virtue of \eq{e:ttos}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t)})=\ori{v}(t-0)$.

($\ori{\mbox{\rm b}}$) For every $s\in T_{(t,+\infty)}$, the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})=\ori{v}(s)-\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)}).
  \end{equation*}
Passing to the limit as $T\ni s\to t+0$, we get: by Lemma~\ref{l:jumps}
($\ori{\mbox{\rm b}}$),
  \begin{equation*}
\ori{v}(s)-\ori{v}(t)\to\ori{v}(t+0)-\ori{v}(t)=\limsup_{T\ni s\to t+0}e(F(t),F(s)),
  \end{equation*}
and by \eq{e:ttoi}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)})\to{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(t,+\infty)})$.
\qed\end{pf}

full.raw:
In order to prove the reverse inequality, let $\xi\in\mathbb{R}$ be arbitrary such that
$\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$. Then, there are $m\in\mathbb{N}$ and a partition $\pi=\{t_i\}_{i=0}^m$
of $T$ such that the first inequality in \eq{e:xi1} holds. If $t_m\le t$, then $\pi$ is a
partition of $T_{(-\infty,t]}$, and if $t\le t_0$, then $\pi$ is a partition of $T_{[t,+\infty)}$,
and so, in the either case, the first inequality in \eq{e:xi1} implies
  \begin{equation} \label{e:x2}
\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)}).
  \end{equation}
Now, suppose $t_{k-1}\le t\le t_k$ for some $k\in\{1,\dots,m\}$. By the triangle
inequality for~$e$, we have
  \begin{equation} \label{e:kk}
e(F(t_{k-1}),F(t_k))\le e(F(t_{k-1}),F(t))+e(F(t),F(t_k)).
  \end{equation}
Since $\{t_i\}_{i=0}^{k-1}\cup\{t\}$ is a partition of $T_{(-\infty,t]}$ and
$\{t\}\cup\{t_i\}_{i=k}^m$ is a partition of $T_{[t,+\infty)}$, from the first inequality
in \eq{e:xi1} and \eq{e:kk}, once again we get \eq{e:x2}. By the arbitrariness
 of $\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$,
\eq{e:x2} implies
   \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(-\infty,t]})+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)}),
  \end{equation*}
 which was to be proved.
\qed\end{pfadd}

($\!\Leftarrow$) Let $m\in\mathbb{N}$ and $\pi=\{t_i\}_{i=0}^m$ be a partition of $T$.
Since $t_{i-1}\le t_i$ for all $i=1,\dots,m$, by the assumption we get
  \begin{align*}
\sum_{i=1}^me(F(t_{i-1}),F(t_i))&\le\sum_{i=1}^m\bigl(\varphi(t_i)-\varphi(t_{i-1})\bigr)
  =\varphi(t_m)-\varphi(t_0)\\
&\le\sup_{t\in T}\varphi(t)-\inf_{s\in T}\varphi(s)=\mbox{\rm V}(\varphi,T)<+\infty.
  \end{align*}
It remains to take the supremum over all partitions $\pi$ of $T$.
\qed\end{pf}

\begin{pflsc}
For any $n\in\mathbb{N}$ and $s,t\in T$, the triangle inequality for $e$ implies
  \begin{equation*}
|e(F_n(s),F_n(t))-e(F(s),F(t))|\le d_H(F_n(s),F(s))+d_H(F_n(t),F(t)),
  \end{equation*}
and so, by the pointwise convergence of $F_n$ to $F$, $e(F_n(s),F_n(t))\!\to\! e(F(s),F(t))$
as $n\to\infty$. Given $m\in\mathbb{N}$ and a partition $\pi=\{t_i\}_{i=0}^m$ of $T$,
by definition of~${\scriptstyle\overrightarrow{\mbox{\rm V}}}$,
  \begin{equation*}
\sum_{i=1}^m e(F_n(t_{i-1}),F_n(t_i))\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T)\quad\mbox{for all \,\,$n\in\mathbb{N}$.}
  \end{equation*}
Passing to the limit inferior as $n\to\infty$, we get
  \begin{equation*}
\sum_{i=1}^m e(F(t_{i-1}),F(t_i))\le\liminf_{n\to\infty}{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F_n,T),
  \end{equation*}
and it remains to take the supremum over all partitions $\pi$ of $T$.
\qed\end{pflsc}

\begin{plim}
Since $\ori{v}$ is nondecreasing on $T$, the limit on the right in \eq{e:ttos} (with $\mbox{\rm V}$
replaced by~${\scriptstyle\overrightarrow{\mbox{\rm V}}}$) exists in $[0,+\infty]$ and is equal to $\sup_{t\in T}\ori{v}(t)$.
Given $t\in T$, we have $T_{(-\infty,t]}\subset T$, and so, $\ori{v}(t)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$,
which implies $\lim_{T\ni t\to s}\ori{v}(t)\le{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$. Conversely, given $\xi\in\mathbb{R}$
with $\xi<{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$, there are $m\in\mathbb{N}$ and a partition $\pi=\{t_i\}_{i=0}^m$ of $T$
(and so, \mbox{$t_0\le t_1\le\dots\le t_{m-1}\le t_m<s$}) such that
  \begin{equation*}
\xi<\sum_{i=1}^m e(F(t_{i-1}),F(t_i))\le\ori{v}(t_m)\le\lim_{T\ni t\to s}\ori{v}(t).
  \end{equation*}
Passing to the limit as $\xi\to{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)$, we get ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T)\le\lim_{T\ni t\to s}\ori{v}(t)$.
\qed\end{plim}

($\ori{\mbox{\rm b}}$) For every $s\in T_{(t,+\infty)}$, the additivity of ${\scriptstyle\overrightarrow{\mbox{\rm V}}}$ implies
  \begin{equation*}
{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[t,+\infty)})=\ori{v}(s)-\ori{v}(t)+{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)}).
  \end{equation*}
Passing to the limit as $T\ni s\to t+0$, we get: by Lemma~\ref{l:jumps}
($\ori{\mbox{\rm b}}$),
  \begin{equation*}
\ori{v}(s)-\ori{v}(t)\to\ori{v}(t+0)-\ori{v}(t)=\limsup_{T\ni s\to t+0}e(F(t),F(s)),
  \end{equation*}
and by \eq{e:ttoi}, ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{[s,+\infty)})\to{\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_{(t,+\infty)})$.
\qed\end{pf}

items.raw:
\vspace{2pt}
(c) $e(X,Y)<+\infty$ provided $X$ and $Y$ are bounded (and, in particular bounded
and closed, or compact).

The well-known properties of $e(\cdot,\cdot)$ are as follows. Given $X,Y,Z\subset M$:
\par\vspace{2pt}
(a) $e(X,Y)\!=\!0$ iff\footnote{`iff' means as usual `if and only if'.} $X\!\subset\!\ov{Y}$,
where $\ov{Y}\!=\!\bigcap_{r>0}\mathcal{O}_r(Y)$ is the closure of $Y$~in~$M$;
\par\vspace{2pt}
(b) $e(X,Y)\le e(X,Z)+e(Z,Y)$ (triangle inequality for~$e$);
\par\vspace{2pt}
(c) $e(X,Y)<+\infty$ provided $X$ and $Y$ are bounded (and, in particular bounded
and closed, or compact).

This finishes the proof of Theorem~\ref{t:A}. Note that we have shown a little
bit more: inequality \eq{RR} holds provided ${\scriptstyle\overrightarrow{\mbox{\rm V}}}(F,T_+)$ and ${\scriptstyle\overleftarrow{\mbox{\rm V}}}(F,T_-)$ are finite.
\qed\end{pfA}

